import { chromium } from "playwright-core";

const BASE = "http://localhost:9377";
const CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const results = [];
const check = (name, ok, detail = "") => {
  results.push({ name, ok });
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${detail ? `  -> ${detail}` : ""}`);
};

const browser = await chromium.launch({ executablePath: CHROME, headless: true });

async function newPage({ width, height, colorScheme = "light" }) {
  const context = await browser.newContext({ viewport: { width, height }, colorScheme });
  const page = await context.newPage();
  const problems = [];
  page.on("console", (msg) => {
    if (msg.type() === "error" || msg.type() === "warning") problems.push(`${msg.type()}: ${msg.text()}`);
  });
  page.on("pageerror", (err) => problems.push(`pageerror: ${err.message}`));
  return { context, page, problems };
}

const summaryText = (page) => page.locator('section[aria-label="Overlap summary"]').innerText().catch(() => "");
const visibleTable = (page) => page.locator("table:visible");
const emeraldCells = (page) => page.locator("table:visible td.bg-emerald-500").count();
const rowCount = (page) => page.locator("table:visible tbody tr").count();

// ---------- Desktop: defaults ----------
{
  const { context, page, problems } = await newPage({ width: 1440, height: 1000 });
  await page.goto(BASE, { waitUntil: "networkidle" });
  await page.waitForSelector("table:visible");

  check("title is model name", (await page.title()) === "Claude Haiku 5.5", await page.title());
  check("h1 is model name", (await page.locator("h1").innerText()) === "Claude Haiku 5.5");
  check("3 default rows", (await rowCount(page)) === 3, `${await rowCount(page)}`);

  const names = await page.locator("table:visible tbody th button").allInnerTexts();
  check("default order SF, Denpasar, Geneva", JSON.stringify(names) === JSON.stringify(["San Francisco", "Denpasar", "Geneva"]), names.join(","));

  const summary = await summaryText(page);
  check("meeting summary shows 2 hours", summary.includes("2") && summary.includes("hours for everyone"), summary.replace(/\s+/g, " ").slice(0, 120));

  const chips = await page.locator('ul[aria-label="Overlap windows"] li').allInnerTexts();
  check("chips are 7am — 8am and 10pm — 11pm", JSON.stringify(chips) === JSON.stringify(["7am — 8am", "10pm — 11pm"]), chips.join(" | "));

  check("green cells = 2 hours × 3 rows = 6", (await emeraldCells(page)) === 6, `${await emeraldCells(page)}`);

  const hint = await page.locator("footer").innerText();
  check("hint text present", hint.includes("Green cells = everyone awake"), hint.replace(/\s+/g, " "));

  const refBadge = await page.locator("table:visible span", { hasText: /^Ref$/ }).count();
  check("one REF badge", refBadge === 1, `${refBadge}`);

  const ariaProblems = problems.filter((p) => !p.includes("[Fast Refresh]"));
  check("no console errors/warnings on load", ariaProblems.length === 0, ariaProblems.join(" || ").slice(0, 300));

  await page.screenshot({ path: ".verify/desktop-light.png", fullPage: true });
  await context.close();
}

// ---------- Desktop dark ----------
{
  const { context, page } = await newPage({ width: 1440, height: 1000, colorScheme: "dark" });
  await page.goto(BASE, { waitUntil: "networkidle" });
  await page.waitForSelector("table:visible");
  await page.screenshot({ path: ".verify/desktop-dark.png", fullPage: true });
  await context.close();
}

// ---------- Interactions on desktop ----------
{
  const { context, page, problems } = await newPage({ width: 1440, height: 1000 });
  await page.goto(BASE, { waitUntil: "networkidle" });
  await page.waitForSelector("table:visible");

  // Base mode
  await page.getByRole("button", { name: "Base", exact: true }).click();
  const baseSummary = (await summaryText(page)).replace(/\s+/g, " ");
  check("base summary heading", baseSummary.includes("Overlap with San Francisco"), baseSummary.slice(0, 160));
  const baseEntries = await page.locator('section[aria-label="Overlap with reference"] li').count();
  check("base summary has 2 entries", baseEntries === 2, `${baseEntries}`);
  check("base overlap cells = 8 + 8", (await emeraldCells(page)) === 16, `${await emeraldCells(page)}`);
  await page.screenshot({ path: ".verify/desktop-base.png", fullPage: true });

  // Back to meeting, then promote Geneva
  await page.getByRole("button", { name: "Meeting", exact: true }).click();
  await page.getByRole("button", { name: "Geneva", exact: true }).click();
  const order = await page.locator("table:visible tbody th button").allInnerTexts();
  check("promote Geneva moves it to the top", order[0] === "Geneva" && order[1] === "San Francisco", order.join(","));
  const refBadge = await page.locator("table:visible span", { hasText: /^Ref$/ }).first().evaluate((el) => el.closest("tr")?.querySelector("button")?.textContent);
  check("REF badge follows the promoted city", refBadge === "Geneva", `${refBadge}`);
  const summaryAfterPromote = (await summaryText(page)).replace(/\s+/g, " ");
  check("summary shows times in Geneva time", summaryAfterPromote.includes("Geneva time"), summaryAfterPromote.slice(0, 100));

  // Restore SF as reference
