  check("base summary has 2 entries", baseEntries === 2, `${baseEntries}`);
  check("base overlap cells = 8 + 8", (await emeraldCells(page)) === 16, `${await emeraldCells(page)}`);
  await page.screenshot({ path: ".verify/desktop-base.png", fullPage: true });

  // Back to meeting, then promote Geneva
  await page.getByRole("button", { name: "Meeting", exact: true }).click();
  await page.getByRole("button", { name: "Geneva", exact: true }).click();
  const order = await page.locator("table:visible tbody th button").allInnerTexts();
  check("promote Geneva moves it to the top", order[0] === "Geneva" && order[1] === "San Francisco", order.join(","));
  const refBadge = await page.locator("table:visible span", { hasText: /^Ref$/ }).first().evaluate((el) => el.closest("tr")?.querySelector("button")?.textContent);
  check("REF badge follows the promoted city", refBadge === "Geneva", `${refBadge}`);
  const summaryAfterPromote = (await summaryText(page)).replace(/\s+/g, " ");
  check("summary shows times in Geneva time", summaryAfterPromote.includes("Geneva time"), summaryAfterPromote.slice(0, 100));

  // Restore SF as reference
  await page.getByRole("button", { name: "San Francisco", exact: true }).click();

  // Remove Denpasar
  await page.getByRole("button", { name: "Remove Denpasar" }).click();
  check("remove drops a row", (await rowCount(page)) === 2, `${await rowCount(page)}`);
  const afterRemove = (await summaryText(page)).replace(/\s+/g, " ");
  check("2 cities: overlap = SF and Geneva (7–13, 22)", afterRemove.includes("8 hours for everyone") || afterRemove.includes("hours for everyone"), afterRemove.slice(0, 120));

  // Add Tokyo via combobox keyboard
  const input = page.getByRole("combobox");
  await input.click();
  await input.fill("tokyo");
  const optionCount = await page.getByRole("option").count();
  check("search 'tokyo' returns Tokyo", optionCount === 1, `${optionCount}`);
  await input.press("Enter");
  const afterAdd = await page.locator("table:visible tbody th button").allInnerTexts();
  check("Enter adds Tokyo at the end", afterAdd[afterAdd.length - 1] === "Tokyo", afterAdd.join(","));
  check("input clears after add", (await input.inputValue()) === "");

  // Search by country + arrow navigation
  await input.fill("india");
  await input.press("ArrowDown");
  await input.press("Enter");
  const afterIndia = await page.locator("table:visible tbody th button").allInnerTexts();
  check("arrow + Enter adds Mumbai via country search", afterIndia.includes("Mumbai"), afterIndia.join(","));

  // Duplicate prevention
  await input.fill("Tokyo");
  const dupCount = await page.getByRole("option").count();
  check("already-added cities are excluded from search", dupCount === 0, `${dupCount}`);
  await input.press("Escape");

  // Reload persistence
  await page.reload({ waitUntil: "networkidle" });
  await page.waitForSelector("table:visible");
  const persisted = await page.locator("table:visible tbody th button").allInnerTexts();
  check("state persists across reload", persisted.join(",") === afterIndia.join(","), persisted.join(","));

  // Settings: overnight + 24h
  await page.getByRole("button", { name: /Awake/ }).click();
  await page.locator("#wake-hour").selectOption("22");
  await page.locator("#sleep-hour").selectOption("6");
  await page.getByRole("button", { name: "24h", exact: true }).click();
