    await page.waitForSelector("table:visible");
    const firstHeader = await page.locator("table:visible thead th").nth(1).innerText();
    const isDesktop = firstHeader.trim() === "12a" || firstHeader.trim() === "12am" || firstHeader.trim() === "0" || firstHeader.trim() === "12a\n";
