import { chromium } from "playwright-core";

const BASE = "http://localhost:9377";
const CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const results = [];
const check = (name, ok, detail = "") => {
  results.push({ name, ok });
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${detail ? `  -> ${detail}` : ""}`);
};

const browser = await chromium.launch({ executablePath: CHROME, headless: true });

async function newPage({ width, height, colorScheme = "light" }) {
  const context = await browser.newContext({ viewport: { width, height }, colorScheme });
  const page = await context.newPage();
  const problems = [];
  page.on("console", (msg) => {
    if (msg.type() === "error" || msg.type() === "warning") problems.push(`${msg.type()}: ${msg.text()}`);
  });
  page.on("pageerror", (err) => problems.push(`pageerror: ${err.message}`));
  return { context, page, problems };
}

const summaryText = (page) => page.locator('section[aria-label="Overlap summary"]').innerText().catch(() => "");
const visibleTable = (page) => page.locator("table:visible");
const emeraldCells = (page) => page.locator("table:visible td.bg-emerald-500").count();
const rowCount = (page) => page.locator("table:visible tbody tr").count();

// ---------- Desktop: defaults ----------
{
  const { context, page, problems } = await newPage({ width: 1440, height: 1000 });
  await page.goto(BASE, { waitUntil: "networkidle" });
  await page.waitForSelector("table:visible");

  check("title is model name", (await page.title()) === "Claude Haiku 5.5", await page.title());
  check("h1 is model name", (await page.locator("h1").innerText()) === "Claude Haiku 5.5");
  check("3 default rows", (await rowCount(page)) === 3, `${await rowCount(page)}`);

  const names = await page.locator("table:visible tbody th button").allInnerTexts();
  check("default order SF, Denpasar, Geneva", JSON.stringify(names) === JSON.stringify(["San Francisco", "Denpasar", "Geneva"]), names.join(","));

  const summary = await summaryText(page);
  check("meeting summary shows 2 hours", summary.includes("2") && summary.includes("hours for everyone"), summary.replace(/\s+/g, " ").slice(0, 120));

  const chips = await page.locator('ul[aria-label="Overlap windows"] li').allInnerTexts();
  check("chips are 7am — 8am and 10pm — 11pm", JSON.stringify(chips) === JSON.stringify(["7am — 8am", "10pm — 11pm"]), chips.join(" | "));

  check("green cells = 2 hours × 3 rows = 6", (await emeraldCells(page)) === 6, `${await emeraldCells(page)}`);

  const hint = await page.locator("footer").innerText();
  check("hint text present", hint.includes("Green cells = everyone awake"), hint.replace(/\s+/g, " "));

  const refBadge = await page.locator("table:visible span", { hasText: /^Ref$/ }).count();
  check("one REF badge", refBadge === 1, `${refBadge}`);

  const ariaProblems = problems.filter((p) => !p.includes("[Fast Refresh]"));
  check("no console errors/warnings on load", ariaProblems.length === 0, ariaProblems.join(" || ").slice(0, 300));

  await page.screenshot({ path: ".verify/desktop-light.png", fullPage: true });
  await context.close();
}

// ---------- Desktop dark ----------
{
  const { context, page } = await newPage({ width: 1440, height: 1000, colorScheme: "dark" });
  await page.goto(BASE, { waitUntil: "networkidle" });
  await page.waitForSelector("table:visible");
  await page.screenshot({ path: ".verify/desktop-dark.png", fullPage: true });
  await context.close();
}

// ---------- Interactions on desktop ----------
{
  const { context, page, problems } = await newPage({ width: 1440, height: 1000 });
  await page.goto(BASE, { waitUntil: "networkidle" });
  await page.waitForSelector("table:visible");

  // Base mode
  await page.getByRole("button", { name: "Base", exact: true }).click();
  const baseSummary = (await summaryText(page)).replace(/\s+/g, " ");
  check("base summary heading", baseSummary.includes("Overlap with San Francisco"), baseSummary.slice(0, 160));
  const baseEntries = await page.locator('section[aria-label="Overlap with reference"] li').count();
  check("base summary has 2 entries", baseEntries === 2, `${baseEntries}`);
  check("base overlap cells = 8 + 8", (await emeraldCells(page)) === 16, `${await emeraldCells(page)}`);
  await page.screenshot({ path: ".verify/desktop-base.png", fullPage: true });

  // Back to meeting, then promote Geneva
  await page.getByRole("button", { name: "Meeting", exact: true }).click();
  await page.getByRole("button", { name: "Geneva", exact: true }).click();
  const order = await page.locator("table:visible tbody th button").allInnerTexts();
  check("promote Geneva moves it to the top", order[0] === "Geneva" && order[1] === "San Francisco", order.join(","));
  const refBadge = await page.locator("table:visible span", { hasText: /^Ref$/ }).first().evaluate((el) => el.closest("tr")?.querySelector("button")?.textContent);
  check("REF badge follows the promoted city", refBadge === "Geneva", `${refBadge}`);
  const summaryAfterPromote = (await summaryText(page)).replace(/\s+/g, " ");
  check("summary shows times in Geneva time", summaryAfterPromote.includes("Geneva time"), summaryAfterPromote.slice(0, 100));

  // Restore SF as reference
  await page.getByRole("button", { name: "San Francisco", exact: true }).click();

  // Remove Denpasar
  await page.getByRole("button", { name: "Remove Denpasar" }).click();
  check("remove drops a row", (await rowCount(page)) === 2, `${await rowCount(page)}`);
  const afterRemove = (await summaryText(page)).replace(/\s+/g, " ");
  check("2 cities: SF + Geneva share 8 hours", afterRemove.includes("8 hours for everyone"), afterRemove.slice(0, 120));

  // Add Tokyo via combobox keyboard
  const input = page.getByRole("combobox");
  await input.click();
  await input.fill("tokyo");
  const optionCount = await page.getByRole("option").count();
  check("search 'tokyo' returns Tokyo", optionCount === 1, `${optionCount}`);
  await input.press("Enter");
  const afterAdd = await page.locator("table:visible tbody th button").allInnerTexts();
  check("Enter adds Tokyo at the end", afterAdd[afterAdd.length - 1] === "Tokyo", afterAdd.join(","));
  check("input clears after add", (await input.inputValue()) === "");

  // Search by country + arrow navigation
  await input.fill("india");
  await input.press("ArrowDown");
  await input.press("Enter");
  const afterIndia = await page.locator("table:visible tbody th button").allInnerTexts();
  check("arrow + Enter adds Mumbai via country search", afterIndia.includes("Mumbai"), afterIndia.join(","));

  // Duplicate prevention
  await input.fill("Tokyo");
  const dupCount = await page.getByRole("option").count();
  check("already-added cities are excluded from search", dupCount === 0, `${dupCount}`);
  await input.press("Escape");

  // Reload persistence
  await page.reload({ waitUntil: "networkidle" });
  await page.waitForSelector("table:visible");
  const persisted = await page.locator("table:visible tbody th button").allInnerTexts();
  check("state persists across reload", persisted.join(",") === afterIndia.join(","), persisted.join(","));

  // Settings: overnight + 24h
  await page.getByRole("button", { name: /Awake/ }).click();
  await page.locator("#wake-hour").selectOption("22");
  await page.locator("#sleep-hour").selectOption("6");
  await page.getByRole("button", { name: "24h", exact: true }).click();
  const settingsText = (await page.locator("#awake-settings").innerText()).replace(/\s+/g, " ");
  check("overnight window readout", settingsText.includes("(overnight)") && settingsText.includes("Awake 8 hours"), settingsText.slice(0, 160));
  const headerLabels = await page.locator("table:visible thead th").allInnerTexts();
  check("24h header labels", headerLabels.includes("00") && headerLabels.includes("23"), headerLabels.slice(0, 5).join(","));

  // Equal window → alert
  await page.locator("#sleep-hour").selectOption("22");
  check("equal hours shows alert", (await page.getByRole("alert").count()) === 1);
  await page.locator("#sleep-hour").selectOption("6");

  await page.getByRole("button", { name: "12h", exact: true }).click();
  await page.locator("#wake-hour").selectOption("7");
  await page.locator("#sleep-hour").selectOption("23");

  // Hover crosshair
  const cell = page.locator("table:visible tbody tr").first().locator("td").nth(10);
  await cell.hover();
  const hovered = await page.locator("table:visible tbody tr").first().locator("td").nth(10).evaluate((el) => el.className.includes("ring-2"));
  check("column hover ring applied", hovered);

  const ariaProblems = problems.filter((p) => !p.includes("[Fast Refresh]"));
  check("no console errors during interactions", ariaProblems.length === 0, ariaProblems.join(" || ").slice(0, 400));

  await page.screenshot({ path: ".verify/desktop-after-edits.png", fullPage: true });
  await context.close();
}

// ---------- Zero overlap warning ----------
{
  const { context, page } = await newPage({ width: 1440, height: 1000 });
  await page.goto(BASE, { waitUntil: "networkidle" });
  await page.waitForSelector("table:visible");
  await page.getByRole("button", { name: /Awake/ }).click();
  await page.locator("#wake-hour").selectOption("9");
  await page.locator("#sleep-hour").selectOption("10");
  const summary = (await summaryText(page)).replace(/\s+/g, " ");
  check("tiny window → zero overlap warning", summary.includes("No overlap. Someone is always asleep"), summary.slice(0, 140));
  await page.screenshot({ path: ".verify/zero-overlap.png", fullPage: false });
  await context.close();
}

// ---------- Mobile ----------
{
  const { context, page, problems } = await newPage({ width: 390, height: 844 });
  await page.goto(BASE, { waitUntil: "networkidle" });
  await page.waitForSelector("table:visible");
  const visibleTables = await page.locator("table:visible").count();
  check("mobile shows exactly one grid", visibleTables === 1, `${visibleTables}`);
  const headerCols = await page.locator("table:visible thead th").count();
  check("mobile: header has 1 + 3 city columns", headerCols === 4, `${headerCols}`);
  const bodyRows = await page.locator("table:visible tbody tr").count();
  check("mobile: 24 hour rows", bodyRows === 24, `${bodyRows}`);
  const overlapCells = await emeraldCells(page);
  check("mobile: 2 hours × 3 cols = 6 overlap cells", overlapCells === 6, `${overlapCells}`);
  const ariaProblems = problems.filter((p) => !p.includes("[Fast Refresh]"));
  check("mobile: no console errors", ariaProblems.length === 0, ariaProblems.join(" || ").slice(0, 300));
  await page.screenshot({ path: ".verify/mobile.png", fullPage: true });
  await context.close();
}

// ---------- Breakpoint at 768 ----------
{
  for (const [width, expectTable] of [[767, "mobile"], [768, "desktop"]]) {
    const { context, page } = await newPage({ width, height: 900 });
    await page.goto(BASE, { waitUntil: "networkidle" });
    await page.waitForSelector("table:visible");
    const rows = await page.locator("table:visible tbody tr").count();
    const expectedRows = expectTable === "desktop" ? 3 : 24;
    check(`breakpoint ${width}px uses ${expectTable} layout`, rows === expectedRows, `visible rows=${rows}`);
    await context.close();
  }
}

// ---------- Empty state ----------
{
  const { context, page, problems } = await newPage({ width: 1280, height: 900 });
  await page.goto(BASE, { waitUntil: "networkidle" });
  await page.waitForSelector("table:visible");
  for (const name of ["San Francisco", "Denpasar", "Geneva"]) {
    await page.getByRole("button", { name: `Remove ${name}` }).click();
  }
  check("empty state shown", (await page.getByText("No cities yet").count()) === 1);
  check("summary hidden when empty", (await summaryText(page)) === "");
  await page.screenshot({ path: ".verify/empty.png" });
  await page.reload({ waitUntil: "networkidle" });
  await page.waitForSelector("text=No cities yet");
  check("empty list persists across reload", (await page.getByText("No cities yet").count()) === 1);
  const ariaProblems = problems.filter((p) => !p.includes("[Fast Refresh]"));
  check("empty state: no console errors", ariaProblems.length === 0, ariaProblems.join(" || ").slice(0, 300));
  await context.close();
}

await browser.close();
const failed = results.filter((r) => !r.ok);
console.log(`\n${results.length - failed.length}/${results.length} passed`);
process.exit(failed.length ? 1 : 0);

