    const cells = Array.from(document.querySelectorAll("table:not(.hidden) td")).filter((td) => td.offsetParent !== null && td.querySelector("span.flex"));
    let overflowing = 0; let worst = 0; let total = 0; let cellW = 0;
    for (const td of cells) {
      const style = getComputedStyle(td);
      const inner = td.clientWidth - parseFloat(style.paddingLeft) - parseFloat(style.paddingRight);
      cellW = td.getBoundingClientRect().width;
      for (const span of td.querySelectorAll("span.flex > span")) {
        const r = document.createRange(); r.selectNodeContents(span);
        const w = r.getBoundingClientRect().width;
        total++;
        if (w > inner + 0.5) { overflowing++; worst = Math.max(worst, w - inner); }
      }
    }
    return { cells: cells.length, labelsChecked: total, overflowing, worstPx: Math.round(worst * 10) / 10, cellWidth: Math.round(cellW) };
  });
  console.log(`${width}px`, JSON.stringify(result));
  await page.close();
}
await browser.close();
